def skill():
    x, a, b, c = symbols('x a b c')
    s = solve([x + a + b + c - 1, c, x + a - (1 - a), x + b - Rational(3, 5)], [x, a, b, c], dict=True)[0]
    v = 1 - s[x]
    return v.p + v.q

def standard():
    F = Fraction
    sols = []
    for xn in range(0, 101):
        for an in range(0, 101):
            for bn in range(0, 101):
                cn = 100 - xn - an - bn
                if cn < 0:
                    continue
                if cn == 0 and (xn + an) == (100 - an) and (xn + bn) == 60:
                    sols.append(F(100 - xn, 100))
    v = sols[0]
    return v.numerator + v.denominator

def unique():
    F = Fraction
    out = set()
    for xn in range(0, 101):
        for an in range(0, 101):
            for bn in range(0, 101):
                cn = 100 - xn - an - bn
                if cn == 0 and (xn + an) == (100 - an) and (xn + bn) == 60:
                    v = F(100 - xn, 100)
                    out.add(v.numerator + v.denominator)
    return sorted(out)
